import site from './content/site/index.json'

export const nav = site.nav

export const hero = {
  eyebrow: site.hero.eyebrow,
  name: site.hero.name,
  tagline: site.hero.tagline,
  cta: { label: site.hero.ctaLabel, href: site.hero.ctaHref },
  portrait: { src: site.hero.portraitSrc, alt: site.hero.portraitAlt },
}

export const about = {
  label: site.about.label,
  heading: site.about.heading,
  bio: site.about.bio,
  stats: site.about.stats.map(({ label, value, xIcon }) =>
    xIcon ? { label, value, xIcon: true } : { label, value }
  ),
  movements: {
    label: site.about.movementsLabel,
    items: site.about.movements,
  },
}

export const portfolio = site.portfolioHeader
export const media = site.mediaHeader
export const topics = site.topicsHeader

export const travel = {
  heading: site.travel.heading,
  subtitle: site.travel.subtitle,
  map: { src: site.travel.mapSrc },
  legend: { dive: site.travel.legendDive, visited: site.travel.legendVisited },
}

export const blog = site.blog

export const footer = {
  heading: site.footer.heading,
  contact: site.footer.contact.map((c) => {
    const entry = { label: c.label, value: c.value }
    if (c.href) entry.href = c.href
    if (c.external) entry.external = true
    return entry
  }),
  copyright: site.footer.copyright,
  tagline: site.footer.tagline,
}
